window.NEO_DATA_MK1_KEY = {"set_id":1,"g":{"r_ctw_01":{"blanks":{"1":"creatures","2":"into","3":"surroundings","4":"matching","5":"color","6":"texture","7":"nearby","8":"rocks","9":"soil","10":"copy"},"kr":{"passage":["위장과 의태는 동물이 위험한 환경에서 살아남기 위해 사용하는 두 가지 전략입니다. 많은 생물은 가까운 식물이나 바위, 흙의 색과 질감을 맞춤으로써 자신의 주변 환경에 섞여 듭니다. 또 어떤 동물은 해로운 종의 겉모습을 흉내 내어, 포식자가 경계심에 그들을 피하도록 만듭니다. 이러한 속임수는 눈에 띄거나 공격받을 가능성을 줄여 주기 때문에 자연선택을 통해 널리 퍼졌습니다. 여러 세대를 거치면서 가장 그럴듯한 무늬가 개체군 안에서 더 흔해졌습니다. 오늘날 과학자들은 포식자와 먹이 사이의 끊임없는 다툼 속에서 형태와 행동이 어떻게 함께 진화하는지 이해하기 위해 이러한 적응을 연구합니다."],"blanks":{"1":"**crea__**가 보이는 **명사** 자리예요 — 동사 blend(섞여 들다)의 주어니까요. 위장하는 주체를 가리키는 복수명사가 필요하고, crea로 시작하는 단어는 '**생물체(creatures)**'예요.","2":"'blend ___ their surroundings'는 **'~ 속으로 섞여 든다'**는 뜻이라 **전치사** 자리예요. 앞글자 **in__**(뒤에 두 글자 더)로 시작하면서 '안으로'라는 방향을 담는 전치사는 **into**뿐이에요(in은 뒤 글자가 안 남아요).","3":"소유격 **their** 뒤라 **명사** 자리예요. 동물이 섞여 드는 대상은 '주변 환경'이고, **surrou__**로 시작하는 단어는 '**surroundings**'예요.","4":"전치사 **by** 뒤라 '~함으로써'를 뜻하는 **동명사(-ing)** 자리예요. **matc__**에 맞으면서 색·질감을 '맞춘다'는 뜻은 '**matching**'이에요.","5":"'the ___ and texture'로 texture와 나란히 묶인 **명사** 자리예요. **co__**로 시작하며 흉내 내는 시각 요소는 '**색(color)**'이에요.","6":"and로 color와 병렬된 **명사** 자리예요. **tex__**에 맞고 색과 함께 맞추는 요소는 '**질감(texture)**'이에요.","7":"'of ___ plants'로 plants를 꾸미는 **형용사** 자리예요. **nea__**로 시작하며 '가까이 있는'을 뜻하는 단어는 '**nearby**'예요.","8":"'plants, ___, or soil' 나열 속 **명사** 자리예요. **ro__**로 시작하며 식물·흙과 어울리는 자연물은 '**바위(rocks)**'예요.","9":"or 뒤 마지막 나열 **명사**예요. **so__**로 시작하며 식물·바위와 함께 흉내 낼 자연물은 '**흙(soil)**'이에요.","10":"'Others ___ the appearance'로 주어 뒤 **동사** 자리예요. **co__**로 시작하며 '겉모습을 흉내 낸다'는 뜻은 '**copy**'예요(같은 co라도 5번의 color는 명사라 자리가 달라요)."}}},"r_dl_01":{"q":{"r_dl_01_1":{"a":3,"why":"본문은 셔틀이 27~29일 **'운행하지 않는다(will not run)'**고만 했어요. '시간표를 줄여서 운행한다'는 말은 어디에도 없죠. 그래서 **'축소 운행'이 사실이 아닌 진술**이라 정답이에요. 나머지 셋(명절에 멈춤·다음 주 재개·시내버스 이용 가능)은 본문에 그대로 나와 사실이에요.","wrong":[null,null,null,null],"kr":{"stem":"이메일에 따르면, 다음 중 사실이 아닌 것은 무엇인가요?","opt":["셔틀이 명절 동안 멈춘다","정상 운행이 다음 주에 재개된다","시내버스가 여전히 그 지역을 다닌다","셔틀이 축소된 시간표로 운행한다"]}},"r_dl_01_2":{"a":2,"why":"셔틀이 아예 멈추는 상황에서, 본문은 **'정문 근처의 12번 노선 시내버스는 평소처럼 이용할 수 있다'**고 대안을 제시해요. 그래서 **시내버스(public bus)**가 정답이에요. 셔틀은 축소가 아니라 완전 중단이라 '명절 시간표 셔틀'은 오답이에요.","wrong":[null,null,null,null],"kr":{"stem":"어떤 대체 교통수단이 언급되나요?","opt":["할인 택시","명절 시간표 셔틀","시내버스","예약 주차 구역"]}}},"kr":{"passage":["날짜: 11월 22일","제목: 명절 기간 셔틀 운행 중단","학생 여러분께,","추수감사절 연휴로 인해 캠퍼스 셔틀이 11월 27일부터 29일까지 운행하지 않음을 알려 드립니다. 정규 운행은 12월 2일 월요일 오전 7시 30분에 재개됩니다. 정문 근처의 12번 노선 시내버스는 평소처럼 이용할 수 있습니다.","감사합니다.","캠퍼스 교통과 드림"]}},"r_dl_02":{"q":{"r_dl_02_1":{"a":3,"why":"메일의 뼈대는 **'주차장이 재포장 기간(4/21~25) 동안 폐쇄된다'**는 안내예요. 견인·비용 같은 벌칙은 폐쇄를 안내하다 딸려 나온 세부일 뿐이라, 글 전체의 목적으로 보긴 어려워요. 그래서 **'폐쇄를 알리는 것'**이 주된 목적이에요.","wrong":[null,null,null,null],"kr":{"stem":"이 이메일의 주된 목적은 무엇인가요?","opt":["새 건물을 알리려고","임대료 인상을 경고하려고","벌칙을 설명하려고","폐쇄를 알리려고"]}},"r_dl_02_2":{"a":1,"why":"앞뒤를 보면, 임시 **허가증**이 '일주일 내내 접근을 **grant** 한다'고 해요. 즉 허가증이 주차장을 **쓸 수 있게 해 준다**는 뜻이죠. 돈을 대는 fund(자금을 대다)나 자리를 떼어 두는 set aside와는 결이 다르고, acknowledge(인정하다)도 권한을 준다는 의미가 없어요. 그래서 **'허용하다(allow)'**가 가장 가까워요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 쓰인 대로 \"grant\"와 의미가 가장 가까운 것은?","opt":["따로 떼어 두다","허용하다","자금을 대다","인정하다"]}},"r_dl_02_3":{"a":2,"why":"정답은 **(C)** 예요. 본문에 기한(4/21 오전 7시)까지 차를 빼지 않으면 **소유자 부담으로 견인(towed at the owner's expense)**된다고 나와요. 소유자 부담 견인은 곧 주민이 비용을 문다는 뜻이라, 기한을 무시하면 돈을 물게 된다는 (C)로 자연스럽게 이어져요. (A) 길거리 주차비 환급은 언급이 없고, (B) 공사 기간 주차장은 폐쇄되어 차를 그대로 둘 수 없으며, (D) 조기 완료 정보도 없어요.","wrong":[null,null,null,null],"kr":{"stem":"이메일에서 추론할 수 있는 것은 무엇인가요?","opt":["단지가 거리 주차 비용을 보전해 준다.","공사 중에도 차를 중앙 주차장에 그대로 둘 수 있다","입주민은 기한을 어기면 비용을 낸다.","재포장이 일찍 끝날 것이다."]}}},"kr":{"passage":["날짜: 4월 8일","제목: 주차장 재포장 및 임시 이동 안내","수신: 전체 입주민","입주민 여러분께,","버치우드 아파트 중앙 주차장이 4월 21일 월요일부터 25일 금요일까지 재포장됨을 알려 드립니다.","이 기간 내내 주차장은 폐쇄되며, 게시된 공지에 따라 모든 차량은 4월 21일 오전 7시 이전에 이동해야 합니다. 남겨진 차량은 소유자 비용으로 견인됩니다.","대안으로, 입주민은 C동 뒤 임시 주차장으로 차량을 옮기거나 호손 거리에 무료로 주차할 수 있습니다. 일주일 내내 이용할 수 있는 임시 허가증은 업무 시간 중 관리 사무소에서 받을 수 있습니다. 협조에 감사드리며 불편을 끼쳐 죄송합니다.","감사합니다.","부동산 관리인 마커스 벨 드림"]}},"r_dl_03":{"q":{"r_dl_03_1":{"a":1,"why":"포스터는 '초보 코딩 **동아리(club)**'가 초보자를 반기며 **'첫 모임에서 등록만 하면 된다'**고 손짓해요. 세부 정보도 있지만 그건 초대를 뒷받침하는 요소일 뿐이고, 유료 '강좌(course)'가 아니라 무료 동아리예요. 그래서 **'동아리로 초대하는 것'**이 목적이에요.","wrong":[null,null,null,null],"kr":{"stem":"이 포스터의 주된 목적은 무엇인가요?","opt":["강좌를 광고하려고","학생들을 동아리로 초대하려고","동아리를 자세히 설명하려고","지원 요건을 나열하려고"]}},"r_dl_03_2":{"a":2,"why":"**'노트북이 없다고요? 대여용 기기를 빌려드려요(loaner machines)'**가 근거예요. loaner는 '빌려주는'이라는 뜻이라 **빌릴 수 있는 노트북**이 정답이에요.","wrong":[null,null,null,null],"kr":{"stem":"컴퓨터가 없는 회원에게 동아리는 무엇을 제공하나요?","opt":["구매 할인","공용 계정","빌릴 수 있는 노트북","인쇄된 학습지"]}},"r_dl_03_3":{"a":0,"why":"**'첫 모임에서 등록만 하면 된다(simply enroll)'**가 근거예요. 회비는 '무료'라 했으니 B는 틀리고, 웹사이트 지원 언급도 없어요. 그래서 **'등록하는 것(enrolling)'**이 방법이에요.","wrong":[null,null,null,null],"kr":{"stem":"학생들은 어떻게 회원이 될 수 있나요?","opt":["등록함으로써","소액의 회비를 내서","웹사이트로 지원해서","모임에 참석해서"]}}},"kr":{"passage":["밑바닥부터 코딩: 초보 코딩 동아리","코드를 한 줄도 안 써 봤나요? 딱 좋아요. 우리 동아리는 완전 초보자에게 매주 직접 해 보는 프로젝트로 프로그래밍을 소개해요. 간단한 게임부터 개인 웹사이트까지 다루면서, 모두가 자기만의 속도로 나아가요. 노트북이 없다고요? 대여용 기기를 빌려드려요.","모임: 매주 화요일 오후 5시 30분~7시, 튜링 랩 3","첫 모임: 9월 9일 — 간식 제공","친근하고 부담 없는 도전 과제로 파이썬, 웹 기초, 팀워크를 배워요.","사전 경험 필요 없어요. 각자 속도는 자기가 정해요.","회비 무료예요. 첫 모임에서 등록만 하면 돼요.","궁금한 점은 동아리 회장 레오 타나카(code@campus.edu)에게 연락하세요."]}},"r_ac_01":{"q":{"r_ac_01_1":{"a":0,"why":"근거는 **'남쪽으로 나는 곤충들은 목적지를 본 적이 없지만, 조상이 쓰던 바로 그 숲에 도착한다'**예요. 즉 **가 본 적 없이도 월동지를 찾아낸다**는 뜻이라 A가 정답이에요. 바로 앞 문장에서 '어느 나비도 왕복 전체를 완주하지 않는다'고 못 박았으니 D는 정반대라 오답이에요.","wrong":[null,null,null,null],"kr":{"stem":"지문은 가을마다 남쪽으로 나는 제왕나비에 대해 무엇을 나타내나요?","opt":["가 본 적이 없는데도 월동지를 찾아낸다.","나이 든 개체가 전에 날아 본 경로로 그들을 이끈다.","자신이 태어난 바로 그 나무로 돌아온다.","각 개체가 자기 일생 동안 왕복 여정 전체를 완주한다."]}},"r_ac_01_2":{"a":1,"why":"둘째 문단은 첫 문장부터 **'여러 단서에 의존한다'**고 선언한 뒤, **태양·체내 시계·자기장**을 차례로 늘어놓아요. 즉 방향을 잡는 **신호들을 제시**하는 문단이라 B가 정답이에요. 밀크위드(C)는 셋째 문단 내용이고, 다른 곤충과의 대조(D)는 나오지 않아요.","wrong":[null,null,null,null],"kr":{"stem":"둘째 문단의 목적은 무엇인가요?","opt":["어린 제왕나비가 성체를 따라 경로를 익힌다고 주장하려고","제왕나비가 방향을 잡는 데 쓰는 신호들을 제시하려고","밀크위드의 소멸이 이주를 위협하는 방식을 보여 주려고","제왕나비의 방향 잡기를 다른 곤충의 방법과 대조하려고"]}},"r_ac_01_3":{"a":"1.2","why":"질문의 핵심어는 **'흐린 날(cloudy)'**이에요. 바로 그 말로 시작하는 세 번째 문장이 **'자기장을 감지해 남쪽 방향을 유지한다'**고 설명하니 정답이에요. 태양(둘째 문장)은 맑은 날 이야기라 달라요.","wrong":[null,null,null,null],"kr":{"stem":"흐린 날에 제왕나비가 어떻게 경로를 유지하는지 설명하는 문장을 클릭하세요.","opt":["과학자들은 제왕나비가 길을 찾기 위해 여러 단서에 의존한다는 것을 발견했다.","그들은 태양의 위치를 나침반으로 삼되, 더듬이 안의 체내 시계로 하루 중 시간을 보정한다.","흐린 날에는 지구의 자기장을 감지하는 듯하며, 이는 남쪽으로 일정한 방향을 유지하도록 돕는다.","서늘한 기온과 짧아진 낮은 이주 세대가 번식을 미루고 지방을 저장하도록 유도한다."]}},"r_ac_01_4":{"a":2,"why":"여기서 striking은 **'유전된 행동의 striking한 예'**로 쓰여, 눈에 확 띄고 인상적이라는 뜻이에요. 그래서 **'놀라운(remarkable)'**이 가장 가까워요. '평범한'은 정반대라 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"\"striking\"과 의미가 가장 가까운 것은?","opt":["평범한","강력한","놀라운","갑작스러운"]}},"r_ac_01_5":{"a":1,"why":"밀크위드 감소는 **'그러나 이 현상은 이제 ... 위협받고 있다'**는 문장에 나와요. '그러나'로 흐름을 틀어 이주를 **위태롭게 하는 요인**으로 제시하는 거예요. 그래서 **'여정을 위협하는 위험을 지적한다'**가 정답이에요. 애벌레(caterpillar)가 먹는 것이지 다 자란 나비의 먹이가 아니라 A도 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 \"밀크위드의 감소\"를 언급하나요?","opt":["다 자란 제왕나비가 겨울 동안 무엇을 먹는지 밝히려고","나비들의 여정을 위협하는 위험을 지적하려고","밀크위드가 번식을 애벌레에 의존한다고 시사하려고","이주 세대가 어떻게 영양분을 모으는지 이야기하려고"]}}},"kr":{"passage":["가을마다 수백만 마리의 제왕나비가 북아메리카의 번식지를 떠나 수천 킬로미터를 날아, 멕시코 중부의 숲에서 겨울을 납니다. 이 여정을 이토록 놀랍게 만드는 것은, 어느 한 마리의 나비도 왕복 여정 전체를 완주하지 않는다는 점입니다. 남쪽으로 나는 곤충들은 목적지를 본 적이 없지만, 어찌 된 일인지 여러 세대 전의 조상이 이용하던 바로 그 작은 숲에 도착합니다.","과학자들은 제왕나비가 길을 찾기 위해 여러 단서에 의존한다는 것을 발견했습니다. 그들은 태양의 위치를 나침반으로 삼되, 더듬이 안에 있는 체내 시계로 하루 중 시간을 보정합니다. 흐린 날에는 지구의 자기장을 감지하는 듯하며, 이는 남쪽으로 일정한 방향을 유지하도록 돕습니다. 서늘한 기온과 짧아진 낮은 이주 세대가 번식을 미루고 긴 비행에 대비해 지방을 저장하도록 유도합니다.","제왕나비의 이주는 유전된 행동의 뚜렷한 예를 보여 주는데, 경로에 대한 지식이 학습이 아니라 유전적으로 전해지기 때문입니다. 그러나 이 현상은 이제 제왕나비 애벌레가 먹는 유일한 식물인 밀크위드의 감소로 위협받고 있습니다. 이 나비들이 어떻게 길을 찾는지 이해하는 것은, 자연에서 가장 놀라운 여정 가운데 하나를 보전하는 데 도움이 될 수 있습니다."]}},"r_ctw_02":{"blanks":{"1":"and","2":"snow","3":"slowly","4":"the","5":"until","6":"reach","7":"porous","8":"deep","9":"the","10":"The"},"kr":{"passage":["대수층은 물을 저장하고 운반하는 지하의 암석층이나 모래층입니다. 비와 녹은 눈은 다공성 층에 이를 때까지 흙을 통해 천천히 스며듭니다. 그 물은 알갱이 사이의 작은 틈을 매우 느리게 이동하며 여러 해 동안 그곳에 머물 수 있습니다. 사람들은 우물을 파고 물을 끌어 올려 이 숨은 수원을 마시는 물과 농사에 씁니다. 건조한 여러 지역에서는 지하수가 이용할 수 있는 담수의 주된 공급원입니다. 그러나 비가 채워 주는 속도보다 빠르게 물을 빼내면 수위가 낮아지고 위쪽 땅이 꺼질 수 있습니다."],"blanks":{"1":"'Rain ___ melting snow'로 두 주어(비·녹은 눈)를 잇는 **등위접속사** 자리예요. **a__**로 시작하며 'A와 B'로 병렬하는 접속사는 '**and**'예요.","2":"**melting**(녹는)이 꾸미는 **명사** 자리예요. **sn__**로 시작하며 비와 함께 스며드는 것은 '**눈(snow)**'이에요.","3":"동사 **sink**(스며들다)를 꾸미는 **부사** 자리예요. **slo__**로 시작하고, 뒤 문장의 '매우 느리게'와 이어지는 '**slowly**'가 와요.","4":"'through ___ soil'로 특정한 그 흙을 가리키는 **관사** 자리예요. **t__**로 시작하는 정관사는 '**the**'뿐이에요.","5":"'...soil ___ they reach...'로 두 절을 잇는 **접속사** 자리예요. **un__**로 시작하며 '~할 때까지'를 뜻하는 '**until**'이 와요.","6":"주어 **they** 뒤 **동사** 자리예요. **re__**로 시작하며 '이 층에 다다른다'는 뜻은 '**reach**'예요.","7":"'these ___ layers'로 layers를 꾸미는 **형용사** 자리예요. 물이 스며드는 층이니 '구멍 많은'을 뜻하고, **por__**로 시작하는 '**porous**'가 와요.","8":"'layers ___ below the surface'로 layers를 뒤에서 꾸미는 자리예요. **de__**로 시작하며 '깊이(아래)'를 뜻하는 '**deep**'이 와요.","9":"'below ___ surface'로 지표면을 가리키는 **관사** 자리예요. **t__**로 시작하는 정관사 '**the**'예요.","10":"문장 첫머리 명사(water) 앞 **관사** 자리예요. 앞서 말한 바로 그 물을 가리키니, 대문자로 시작하는 정관사 '**The**'가 와요."}}},"r_dl_04":{"q":{"r_dl_04_1":{"a":0,"why":"본문이 **'위층 이동에 도움이 필요하면 미리 연락하라'**고 안내한다는 건, 계단만으로는 이동이 어려운 사람이 있을 수 있음을 전제해요. 그래서 **'일부는 도움이 필요할 수 있다'**가 자연스러운 추론이에요. 점검은 하루(8시~13시)뿐이고 계단은 오히려 이용하라고 했으니 나머지는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"공지에서 추론할 수 있는 것은 무엇인가요?","opt":["일부는 도움이 필요할 수 있다.","엘리베이터가 교체되고 있다.","점검이 이틀 걸린다.","계단이 폐쇄될 것이다."]}},"r_dl_04_2":{"a":2,"why":"**'건물 양쪽 끝의 계단(stairwells)을 이용해 달라'**가 직접적인 근거예요. 그래서 **계단(stairs)**이 정답이에요.","wrong":[null,null,null,null],"kr":{"stem":"엘리베이터를 쓸 수 없는 동안 사람들은 무엇을 이용해야 하나요?","opt":["임시 승강기","지하 화물 엘리베이터","계단","위층 출입구"]}}},"kr":{"passage":["엘리베이터 점검 — 컨 홀","컨 홀의 승객용 엘리베이터 두 대가 연례 안전 점검을 위해 11월 6일 목요일 오전 8시부터 오후 1시까지 일시적으로 이용할 수 없습니다. 이 시간 동안에는 건물 양쪽 끝의 계단을 이용해 주세요. 위층으로 이동하는 데 도움이 필요하면 미리 내선 4120번 안내 데스크로 연락해 주세요."]}},"r_dl_05":{"q":{"r_dl_05_1":{"a":0,"why":"**'1위를 차지할 만하다', '숨이 멎을 정도', '강력 추천', 4.5점**처럼 극찬이 글 전체에 깔려 있어요. 주차·식수대 같은 주의점을 덧붙여도 그건 실망이 아니라 친절한 팁이라, 태도는 **'열광적(Enthusiastic)'**이에요. 사실만 나열한 게 아니라 감정이 뚜렷해서 '사실적'도 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"이 코스에 대한 글쓴이의 전반적인 태도를 가장 잘 나타낸 것은?","opt":["열광적","실망함","사실적","경계함"]}},"r_dl_05_2":{"a":1,"why":"**'작은 주차장이 놀랄 만큼 빨리 차니 일찍 오라'**고 했어요. 뒤집으면 늦게 오면 **주차 자리가 없을 수 있다**는 뜻이라 B가 정답이에요. '입장 거부'까지는 말하지 않았으니 C는 지나친 해석이에요.","wrong":[null,null,null,null],"kr":{"stem":"늦게 도착하는 등산객에 대해 무엇을 추론할 수 있나요?","opt":["입장료를 더 낼 수 있다.","주차 자리를 못 찾을 수 있다.","입장이 거부될 것이다.","정상 화장실을 써야 한다."]}},"r_dl_05_3":{"a":3,"why":"이유가 문장에 딱 붙어 있어요 — **'들머리의 식수대가 고장 나 있어서(the water fountain ... was broken) 물을 넉넉히 챙기라'**고요. 그래서 **'식수대 고장'**이 정답이에요. 바람·화장실도 언급되지만 '물을 더 챙기라'의 이유로 연결된 건 식수대예요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 예상보다 물을 더 챙기라고 조언하나요?","opt":["정상이 바람이 세서","매점이 물을 팔지 않아서","화장실이 부족해서","식수대가 고장 나 있어서"]}}},"kr":{"passage":["디에고의 트레일 노트","토요일에 폭스글렌 공원의 리지라인 루프에 다녀왔는데, 올해 수십 개의 코스를 걸었지만 이 코스가 1위를 차지할 만해요. 길이는 약 7마일이고 중간쯤에 가파른 구간이 딱 한 군데 있어서, 세 시간은 잡는 게 좋고 정상의 바람이 워낙 거세니 옷은 겹겹이 입기를 강력히 권해요. 골짜기를 굽어보는 탁 트인 전망은 정말 숨이 멎을 정도였는데, 특히 사람들이 몰리기 전 아침 여덟 시쯤이 좋았어요. 실용적인 주의 두 가지: 생각보다 작은 주차장이 놀랄 만큼 빨리 차니 일찍 도착하고, 들머리의 식수대가 고장 나 있어서 생각보다 물을 넉넉히 챙기는 게 좋아요. 화장실은 아쉽게도 입구에만 있어요. 공식적으로는 '보통' 난이도지만, 초보자도 중간중간 쉬어 가면 충분히 해낼 수 있어요. 주말에 재충전이 필요한 분께 강력 추천해요.","총평: 이른 아침에 걷기 좋은 보통 난이도의 7마일 루프. 5점 만점에 4.5점."]}},"r_ctw_03":{"blanks":{"1":"prevailing","2":"gradually","3":"these","4":"driving","5":"steadily","6":"barren","7":"Individual","8":"climb","9":"gentle","10":"slope"},"kr":{"passage":["모래 언덕은 영구적으로 보일지 몰라도, 지구에서 가장 쉼 없이 움직이는 지형에 속합니다. 강한 탁월풍은 이 언덕들을 서서히 다시 빚어내며, 메마른 사막을 가로질러 꾸준히 밀고 나갑니다. 개별 모래알은 완만한 바람맞이 비탈을 기어오른 뒤 아래로 굴러떨어지며, 이 끊임없는 과정이 언덕 전체를 천천히 옮겨 놓습니다. 탁월풍은 좀처럼 방향을 바꾸지 않기 때문에, 언덕은 여러 세기에 걸쳐 한 방향으로 나아갑니다. 그 굽은 윤곽은 이용할 수 있는 모래의 양과 주변 기류의 움직임에 따라 달라집니다. 억센 식물이 뿌리를 내린 곳에서는, 얽힌 줄기가 흩날리는 모래를 붙잡아 그 전진을 멈출 수 있습니다."],"blanks":{"1":"'Strong ___ winds'로 winds를 꾸미는 **형용사** 자리예요. 뒤에서 '좀처럼 방향을 안 바꾼다'고 하니 '한 방향으로 부는', 즉 '탁월풍의'를 뜻하고, **preva__**로 시작하는 '**prevailing**'이 와요.","2":"동사 **reshape**를 꾸미는 **부사** 자리예요. **grad__**로 시작하며 '서서히'를 뜻하는 '**gradually**'가 와요.","3":"'reshape ___ dunes'로 dunes 앞 **지시어** 자리예요. 앞서 말한 그 언덕을 가리키고, **th__**로 시작하는 '**these**'가 와요.","4":"'___ them across'로 분사구문에서 '밀며'를 뜻하는 자리예요. **dri__**로 시작하며 모래를 몰고 간다는 '**driving**'이 와요.","5":"동사(driving)를 꾸미는 **부사** 자리예요. **stea__**로 시작하며 '꾸준히'를 뜻하는 '**steadily**'가 와요.","6":"'a ___ desert'로 desert를 꾸미는 **형용사** 자리예요. 모래언덕이 있는 '메마른'을 뜻하고, **bar__**로 시작하는 '**barren**'이 와요.","7":"문장 주어(grains)를 꾸미는 **형용사** 자리예요. **Indiv__**로 시작하며 '개별의'를 뜻하는 '**Individual**'이 와요.","8":"주어(grains) 뒤 **동사** 자리예요. **cl__**로 시작하며 비탈을 '기어오른다'는 '**climb**'이 와요.","9":"'the ___ windward slope'로 slope를 꾸미는 **형용사** 자리예요. 모래알이 오르는 바람맞이 쪽은 경사가 '완만한'이고, **gen__**로 시작하는 '**gentle**'이 와요.","10":"'the gentle windward ___'로 마지막 **명사** 자리예요. **sl__**로 시작하며 모래알이 오르는 '비탈'은 '**slope**'예요."}}},"r_ac_02":{"q":{"r_ac_02_1":{"a":0,"why":"원문의 핵심은 두 가지예요 — ① **분화가 깊은 곳에서 일어나 직접 관찰이 안 되니 지표 측정으로 추론**한다, ② 게다가 **불안정이 늘 분화로 끝나지 않아 어렵다**. A가 이 둘을 왜곡 없이 담아요. D는 '불안정이 대개 분화로 이어진다'고 원문과 **반대**로 말해 틀리고, B·C는 인과를 뒤섞었어요.","wrong":[null,null,null,null],"kr":{"stem":"음영 표시된 문장의 핵심 정보를 가장 잘 나타낸 것은?","opt":["분화는 깊은 곳에서 쌓이므로 자료는 지표 측정에서만 추론할 수 있는데, 불안정이 늘 분화로 끝나지는 않아 이 일이 까다롭다.","화산학자는 지하 저장소를 간접적으로만 관찰할 수 있지만, 분화가 깊은 곳에 쌓이면서 지표 측정이 그들의 작업을 복잡하게 만들 수 있다.","모든 불안정이 분화로 끝나지는 않기 때문에, 과학자는 지표 측정으로 분화를 예측해야 하며, 이는 지하를 직접 관찰하기 어렵게 만든다.","분화는 지표 아래 아주 깊은 곳에서 일어나 저장소를 직접 관찰하기가 거의 불가능하므로, 과학자들은 불안정이 대개 분화로 이어진다고 추론해 왔다."]}},"r_ac_02_2":{"a":1,"why":"둘째 문단은 **'마그마가 올라오며 주변 암석을 깨 특유의 지진 패턴을 만들고, 이를 지진계로 추적한다'**고 해요. 즉 **용융암이 감시 가능한 지진을 만드는 방식**을 설명하는 문단이라 B가 정답이에요. 지반 융기·기체 변화(A)는 셋째 문단 내용이고, '지진만으로 확실히 예측'(C)은 본문이 오히려 부정해요.","wrong":[null,null,null,null],"kr":{"stem":"둘째 문단의 목적은 무엇인가요?","opt":["분화 직전에 일어나는 지반 융기와 기체 변화를 설명하려고","상승하는 용융암이 어떻게 감시 가능한 지진을 일으키는지 설명하려고","지진 신호만으로 분화를 확실히 예측할 수 있다고 주장하려고","무엇을 화산 불안정으로 세어야 하는지 정의하려고"]}},"r_ac_02_3":{"a":2,"why":"precursors는 **분화에 '앞서(pre-)' 나타나는 것**을 뜻해요. 문맥에서도 뒤이어 나오는 지진·융기 같은 **조짐**을 가리키죠. 그래서 **'경고 신호(warning signs)'**가 가장 가까워요. '최종 결과'는 정반대라 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 \"precursors\"와 의미가 가장 가까운 것은?","opt":["최종 결과","안전 대책","경고 신호","측정 장치"]}},"r_ac_02_4":{"a":3,"why":"셋째 문단이 **'높아지는 압력이 위쪽 지반을 부풀려 융기를 일으킨다'**고 직접 말해요. 그래서 **'위로 부푼다'**가 정답이에요. 지진 패턴(B)은 지반이 아니라 암석 균열 이야기라 자리가 달라요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 화산이 분화에 다가갈 때 마그마 위쪽 지반은","opt":["압력이 서서히 풀리며 가라앉는다","특유의 지진 패턴으로 갈라진다","녹은 기체가 빠져나가며 식는다","압력이 밀어 올려 위로 부푼다"]}},"r_ac_02_5":{"a":0,"why":"바로 앞에서 **'지표들이 함께 강해지면 분화가 임박했다는 근거가 탄탄해진다'**고 했어요. '신호 하나는 애매하다'는 말은 그 **대비**로, **왜 여러 신호가 모여야 확신이 커지는지**를 뒷받침해요. 그래서 A가 정답이고, '하나만으로 충분하다'(B)는 정반대예요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 \"신호 하나만 떼어 놓고 보면 애매할 수 있다\"고 말하나요?","opt":["여러 지표가 함께 강해질수록 확신이 커지는 이유를 설명하려고","지표 하나만으로도 분화 예측이 충분하다고 주장하려고","분화 전에 기체가 성분을 바꾸는 방식을 설명하려고","지표 측정이 더 중요하다는 것을 보여 주려고"]}}},"kr":{"passage":["화산 분화를 예측하려면 마그마가 지표로 상승하기에 앞서 나타나는 미묘한 물리적·화학적 신호를 해석해야 합니다. 분화는 지하 수 킬로미터에서 전개되는 과정의 정점이기 때문에, 화산학자는 마그마 저장소를 직접 관찰할 수 없고 지표에서 모은 간접적인 측정으로 그 상태를 추론해야 하는데, 모든 불안정 징후가 실제 분화로 이어지지는 않는다는 사실이 이 일을 어렵게 만듭니다.","가장 유용한 전조는 지각을 통과하는 용융암의 이동에서 비롯됩니다. 마그마가 위로 올라오면서 주변 암석을 깨뜨리고, 지진계 망으로 그 빈도와 위치를 추적할 수 있는 특유의 작은 지진 패턴을 만들어 냅니다.","동시에, 높아지는 압력이 위쪽 지반을 부풀려 기울기와 고도의 변화로 감지되는 측정 가능한 융기를 일으키고, 마그마에 녹아 있던 기체가 빠져나오며 저장소가 분화에 가까워질수록 그 성분이 변합니다. 이 지표들이 함께 강해지면 분화가 임박했다는 근거가 탄탄해지지만, 신호 하나만 떼어 놓고 보면 애매할 수 있습니다.","지속적인 어려움은 이런 관측을 시점과 규모에 대한 믿을 만한 예측으로 옮기는 데 있습니다. 화산은 저마다 행동이 크게 달라서, 어떤 화산은 몇 달 동안 심상찮은 불안정을 보이다가 아무 일 없이 잠잠해지기도 하고, 거의 예고 없이 분화하기도 합니다. 그래서 예보관들은 결론을 확실성이 아니라 확률로 표현하며, 특정 화산이 정확히 언제 분화할지 예측하는 일은 여전히 현재 과학의 범위를 넘어섭니다."]}},"l_a01":{"q":{"l_a01_1":{"a":1,"why":"내일 예약이 되냐는 물음에 **10시에 빈자리가 있다**며 시간을 제시한 B가 알맞은 응답이에요. A는 book을 '책'으로 받은 함정, C는 위치, D는 안부라 예약 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 책은 다음 주까지 반납해야 해요.","10시에 자리가 하나 비어 있어요.","복도 따라가다 왼쪽에 있어요.","곧 나아질 거예요."]}}},"script":[{"sp":"M","text":"Can I book a checkup for tomorrow?"}],"kr":{"passage":["내일 검진 예약할 수 있을까요?"]}},"l_a02":{"q":{"l_a02_1":{"a":3,"why":"'어떻게' 시작하냐는 물음에 **웹사이트를 확인했는지 되물으며** 안내 경로를 알려 준 D가 자연스러워요. B는 '누가' 담당인지라 how와 안 맞고, C는 예/아니오 대답이라 어색해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["수업은 9시에 시작해요.","Dr. Reyes는 오늘 안 계세요","네, 정말 도움이 돼요.","저희 웹사이트는 확인해 보셨어요?"]}}},"script":[{"sp":"W","text":"How do I start counseling here?"}],"kr":{"passage":["여기서 상담은 어떻게 시작하나요?"]}},"l_a03":{"q":{"l_a03_1":{"a":0,"why":"5시까지만 연다는 정보에 **내일 다시 오겠다**고 반응한 A가 맥락에 맞아요. B는 run을 '달리다'로 받은 함정이고, C·D는 관련 없는 말이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그럼 내일 다시 와 봐야겠네요.","그 사람은 매일 아침 출근 전에 달리기를 해요.","새가 정말 빠르게 날아가 버렸어요.","간호사분이 강연을 잘하셨어요."]}}},"script":[{"sp":"M","text":"The flu clinic runs until five today."}],"kr":{"passage":["오늘 독감 클리닉은 5시까지 운영해요."]}},"l_a04":{"q":{"l_a04_1":{"a":2,"why":"의뢰서가 필요한지 묻는 예/아니오 질문에 **필요 없이 바로 와도 된다(walk-in)**고 답한 C가 정확해요. D는 refer를 반복한 함정, B는 시간 답이라 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 치료사분은 정말 친절해요.","보통 이른 아침이에요.","아니요, 예약 없이 오셔도 돼요.","지난주에 당신을 의뢰해 드렸어요."]}}},"script":[{"sp":"W","text":"Is a referral required for physical therapy?"}],"kr":{"passage":["물리치료에 의뢰서가 필요한가요?"]}},"l_a05":{"q":{"l_a05_1":{"a":1,"why":"약이 준비됐다는 안내에 **지금 가서 받겠다**고 반응한 B가 자연스러워요. A(counter→반박), C(prescription→subscription)는 소리가 비슷한 단어로 만든 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 반박 논거는 설득력이 약했어요.","좋아요, 지금 가서 받아 올게요.","제 구독은 매달 갱신돼요.","약국 줄이 길었어요."]}}},"script":[{"sp":"M","text":"Your prescription is ready at the counter."}],"kr":{"passage":["처방약이 창구에 준비돼 있어요."]}},"l_a06":{"q":{"l_a06_1":{"a":0,"why":"'누구'를 찾아가냐는 물음에 **영양사(dietitian)**라고 사람을 짚어 준 A가 맞아요. B는 '어디'(장소) 답이라 who와 안 맞고, C는 planning을 여행 계획으로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["교내 영양사님이 딱이에요.","웰니스 건물 쪽에 있어요.","우리 곧 여행 갈 계획이에요.","네, 건강해 보이네요."]}}},"script":[{"sp":"W","text":"Who should I see about meal planning?"}],"kr":{"passage":["식단 계획은 누구를 찾아가야 하나요?"]}},"l_a07":{"q":{"l_a07_1":{"a":3,"why":"자리가 있다는 권유성 정보에 **요즘 혼자 요가로 스트레스를 관리 중**이라며 넌지시 반응한 D가 대화로 자연스러워요. A·B는 stress·dress 등 소리만 비슷한 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 가게는 9시에 문 열어요.","그 원피스 정말 잘 어울려요.","기말 주간은 정말 지치네요.","저는 요즘 혼자 요가를 하고 있어요."]}}},"script":[{"sp":"M","text":"The stress workshop still has a few openings."}],"kr":{"passage":["스트레스 워크숍에 아직 몇 자리 남아 있어요."]}},"l_a08":{"q":{"l_a08_1":{"a":2,"why":"'얼마나 오래(how long)' 걸리냐는 물음에 **약 30분**이라고 시간을 답한 C가 정확해요. A는 '어디'(장소), B는 review를 반복한 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["커리어 센터 로비에서요.","메모는 이미 검토했어요.","보통 30분 정도예요.","네, 정말 잘 됐어요."]}}},"script":[{"sp":"W","text":"How long is a resume review?"}],"kr":{"passage":["이력서 첨삭은 시간이 얼마나 걸리나요?"]}},"l_a09":{"q":{"l_a09_1":{"a":0,"why":"마감이 임박했다는 정보에 **곧 제출하겠다**고 반응한 A가 맥락에 맞아요. B는 close를 '닫다'로, C는 March→marsh 소리로 만든 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저도 곧 제출할게요.","창문 좀 닫아 주세요.","그 습지는 봄마다 물이 넘쳐요.","그 회사 정말 대단해 보여요."]}}},"script":[{"sp":"M","text":"Internship applications close at the end of March."}],"kr":{"passage":["인턴십 지원은 3월 말에 마감돼요."]}},"l_a10":{"q":{"l_a10_1":{"a":1,"why":"어떤 회사가 오는지 아느냐는 물음에 **정보가 포털에 다 있다**며 확인 방법을 알려 준 B가 알맞아요. A는 예/아니오만 답해 which를 놓쳤고, C는 coming을 '집에 오다'로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 저도 갈 거예요.","전부 포털에 올라와 있어요.","그 사람은 이번 주말에 집에 와요.","제가 당신 부스를 이미 등록해 뒀어요."]}}},"script":[{"sp":"W","text":"Do you know which companies are coming?"}],"kr":{"passage":["어떤 회사들이 오는지 아세요?"]}},"l_a11":{"q":{"l_a11_1":{"a":3,"why":"예약할 수 있냐는 물음에 **매주 월요일 포털에 예약 자리가 열린다**며 방법을 알려 준 D가 맞아요. B는 위치, C는 면접 감상이라 예약 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["거기서 보는 경치가 좋아요.","엘리베이터 지나서 12호실이에요.","면접은 정말 긴장돼요.","예약 자리는 매주 월요일 포털에 열려요."]}}},"script":[{"sp":"M","text":"Can I schedule a mock interview?"}],"kr":{"passage":["모의 면접을 예약할 수 있을까요?"]}},"l_a12":{"q":{"l_a12_1":{"a":2,"why":"무엇이 돋보이게 하냐는 물음에 **회사별 맞춤 작성이 도움이 된다**고 비결을 답한 C가 정확해요. A는 letter를 '편지'로 받은 함정, D는 '누가' 검토하는지라 what과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["당신 편지가 오늘 아침에 도착했어요.","네, 제 것은 잘 나왔어요.","회사마다 맞춤으로 쓰는 게 도움이 돼요.","보통 지도교수님이 검토해 주세요."]}}},"script":[{"sp":"W","text":"What makes a cover letter stand out?"}],"kr":{"passage":["자기소개서가 돋보이려면 뭐가 중요할까요?"]}},"l_a13":{"q":{"l_a13_1":{"a":0,"why":"'어디서' 열리냐는 물음에 **이번엔 교내가 아닐 것 같다**며 장소 정보를 준 A가 맞아요. B는 '언제'(시간), C·D는 held·mixer를 '문을 잡다·혼합물'로 받은 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["이번엔 교내는 아닐 거예요.","오후 세션 바로 다음이에요.","그 사람이 문을 잡아 줬어요.","혼합물을 천천히 넣으세요."]}}},"script":[{"sp":"M","text":"Where is the networking mixer held?"}],"kr":{"passage":["네트워킹 모임은 어디서 열리나요?"]}},"l_a14":{"q":{"l_a14_1":{"a":1,"why":"신청했냐는 물음에 **막 하려던 참이었다**고 답한 B가 자연스러워요. A는 sign을 '서명'으로 받은 함정, C는 '어디' 답이라 예/아니오 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["여기 하단에 서명해 주세요.","막 하려던 참이었어요.","위층 안내 데스크에서요.","라우팅 번호가 틀렸어요."]}}},"script":[{"sp":"W","text":"Have you signed up for recruiting yet?"}],"kr":{"passage":["채용 프로그램 신청 벌써 했어요?"]}},"l_a15":{"q":{"l_a15_1":{"a":2,"why":"'어떤 서류'가 필요하냐는 물음에 **자격 상황에 따라 다르다**고 답한 C가 알맞아요. A는 '언제'(시간), B는 require→acquire 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["4월 15일 전에요.","최근에 그 건물을 인수했대요.","신분(자격)에 따라 달라요.","네, 저는 쉽게 자격이 됐어요."]}}},"script":[{"sp":"M","text":"Which documents does the scholarship require?"}],"kr":{"passage":["그 장학금은 어떤 서류가 필요한가요?"]}},"l_b01":{"q":{"l_b01_1":{"a":1,"why":"여자가 **'산 지 일주일 만에 모터가 나갔다'**고 이유를 밝혔어요(B). A(더 나은 모델)는 반품이 아니라 '환불'을 원하는 이유이고, C는 '아예 작동 안 했다'로 과장한 오답이에요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 왜 블렌더를 반품하려 하나요?","opt":["다른 곳에서 더 나은 모델을 찾아서","모터가 일주일 만에 멈춰서","블렌더가 아예 작동한 적이 없어서","쓰기엔 소리가 너무 커서"]}},"l_b01_2":{"a":0,"why":"점원이 **'카드로 환불해 주겠다'**고 했어요(A). B는 여자가 거절한 '교환'이고, D의 추가 보상은 대화에 없어요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 환불을 어떤 방식으로 받나요?","opt":["카드로 되돌려받음","새 교체 블렌더로 받음","향후 구매용 매장 적립금으로","환불에 추가 보상금까지"]}}},"script":[{"sp":"W","text":"Hi, I'd like to return this blender. The motor died after just a week."},{"sp":"M","text":"Oh, sorry to hear that. Do you have the receipt?"},{"sp":"W","text":"Yes, here it is. I bought it two weeks ago."},{"sp":"M","text":"Since it's clearly defective, I can exchange it for a new one."},{"sp":"W","text":"Actually, could I get a refund? I found a better model elsewhere."},{"sp":"M","text":"No problem. I'll refund it to your card."},{"sp":"W","text":"How long does that usually take?"},{"sp":"M","text":"About three to five business days."},{"sp":"W","text":"Perfect. You've been a real lifesaver, thanks."}],"kr":{"passage":["여: 이 블렌더 반품하고 싶은데요. 산 지 일주일 만에 모터가 나가 버렸어요.","남: 저런, 죄송합니다. 영수증 있으세요?","여: 네, 여기요. 2주 전에 샀어요.","남: 명백한 불량이니 새 제품으로 교환해 드릴 수 있어요.","여: 사실 환불이 될까요? 다른 데서 더 나은 모델을 찾았거든요.","남: 문제없어요. 카드로 환불해 드릴게요.","여: 보통 얼마나 걸리나요?","남: 영업일 기준 3~5일이요.","여: 완벽하네요. 정말 큰 도움 됐어요, 감사합니다."]}},"l_b02":{"q":{"l_b02_1":{"a":2,"why":"여자가 **'브레이크 밟을 때 끼익 소리가 난다'**고 했어요(C). A는 '완전히 고장'으로 과장했고, B(경고등)는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"여자가 정비소를 찾은 문제는 무엇인가요?","opt":["브레이크가 완전히 고장 남","계기판 경고등","브레이크 밟을 때 나는 고음","급한 당일 차량 인수"]}},"l_b02_2":{"a":0,"why":"여자가 '생각보다 낫다'고 한 건 남자가 **'한 시간쯤 걸린다'**고 한 직후예요. 즉 짧은 소요 시간이 기다리는 이유예요(A). B의 커피·인터넷은 기다리는 동안의 편의일 뿐 결정적 이유는 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 왜 수리를 기다리기로 하나요?","opt":["작업이 한 시간 정도밖에 안 걸려서","로비에 커피와 인터넷이 있어서","수리가 완전히 무료라서","달리 집에 갈 방법이 없어서"]}}},"script":[{"sp":"W","text":"Hi, my car's been making a squealing noise when I brake."},{"sp":"M","text":"That usually means the brake pads are worn down."},{"sp":"W","text":"Is that expensive to fix?"},{"sp":"M","text":"Not too bad, it won't cost an arm and a leg. We can replace them this afternoon."},{"sp":"W","text":"How long will it take?"},{"sp":"M","text":"About an hour, maybe a little more."},{"sp":"W","text":"That's actually better than I expected. Can I wait in the lobby?"},{"sp":"M","text":"Of course. There's coffee and free internet in there."},{"sp":"W","text":"Perfect. Go ahead and take a look, then."},{"sp":"M","text":"Will do. I'll let you know what I find."}],"kr":{"passage":["여: 안녕하세요, 제 차가 브레이크 밟을 때 끼익 소리가 나요.","남: 보통 그건 브레이크 패드가 닳았다는 뜻이에요.","여: 수리비가 비싼가요?","남: 그렇게 심하진 않아요, 큰돈 들 정도는 아니에요. 오늘 오후에 교체해 드릴 수 있어요.","여: 얼마나 걸릴까요?","남: 한 시간쯤, 조금 더 걸릴 수도 있고요.","여: 생각보다 낫네요. 로비에서 기다려도 될까요?","남: 그럼요. 안에 커피랑 무료 인터넷 있어요.","여: 좋아요. 그럼 한번 봐 주세요.","남: 그럴게요. 확인해 보고 알려 드릴게요."]}},"l_c01":{"q":{"l_c01_1":{"a":2,"why":"핵심은 **'낡은 기계를 휴대폰으로 작동하는 새 기계로 교체'**한다는 거예요(C). 앱은 그 조작 수단일 뿐이라 D는 지엽적이고, A(요금 인상)는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"이 안내방송의 주된 내용은 무엇인가요?","opt":["세탁 요금 인상","세탁기 정비 완료","원격으로 조작하는 새 기계","기숙사 관리용 휴대폰 앱"]}},"l_c01_2":{"a":0,"why":"**'다음 주 월요일과 화요일에 닫는다'**고 했으니 이틀간이에요(A). '한 주 내내'는 과장이에요.","wrong":[null,null,null,null],"kr":{"stem":"세탁실은 언제 이용할 수 없나요?","opt":["다음 주 이틀간","한 주 내내","월요일 두 번 정도","화요일 오후에만"]}}},"script":[{"sp":"W","text":"Hey residents, some good news about the laundry room downstairs. Over the break, all of the old machines are being replaced with new ones that you can start right from your phone. You'll download the app, add money to your account, and pick a washer without ever needing coins again. The room will be closed next Monday and Tuesday while the crew installs everything. Once everything's up and running, please report any problems through the app so we can fix them fast."}],"kr":{"passage":["안녕하세요 입주민 여러분, 아래층 세탁실에 대한 반가운 소식이에요. 방학 동안 낡은 기계가 전부 휴대폰으로 바로 작동하는 새 기계로 교체돼요.","앱을 내려받아 계정에 금액을 충전하고, 이제 동전 없이 세탁기를 고르면 돼요.","설치 작업 때문에 다음 주 월·화요일에는 세탁실을 닫아요.","모두 설치되고 나면, 문제가 있을 때 앱으로 신고해 주세요. 빠르게 고칠 수 있게요."]}},"l_c02":{"q":{"l_c02_1":{"a":0,"why":"**'2층 갤러리에서 금요일에 사진전을 연다'**며 전시를 알리고 방문을 권해요(A). 공모전(C)이나 동아리 모집(D)은 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"이 안내방송의 목적은 무엇인가요?","opt":["전시를 홍보하려고","여행 수업 참가자를 모집하려고","사진 공모전을 알리려고","사진 동아리에 초대하려고"]}},"l_c02_2":{"a":2,"why":"**'상당수가 한 번도 전시된 적 없다'**고 했으니 C가 맞아요. 촬영은 '여행 수업' 중이라 해외라고 단정할 수 없고(A), 학생 작품이라 B(전문가)도 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"전시 사진에 대해 추론할 수 있는 것은?","opt":["모든 사진이 해외에서 찍혔다","작가들은 전문가다","일부 작품은 전시된 적이 없다","전시가 일주일간 열린다"]}}},"script":[{"sp":"M","text":"Attention, students! The gallery on the second floor of the arts building is opening a new photography show this Friday. All of the pictures were taken by students during last summer's travel courses, and many of them have never been displayed before. The opening reception starts at five, with light snacks and a chance to meet the photographers. Admission is free, and the show will stay up through the end of the month, so there's plenty of time to swing by."}],"kr":{"passage":["학생 여러분, 주목해 주세요! 예술관 2층 갤러리에서 이번 주 금요일에 새 사진전을 열어요.","모든 사진은 지난여름 여행 수업 중에 학생들이 찍은 것이고, 상당수는 한 번도 전시된 적이 없어요.","개막 리셉션은 5시에 시작하며, 간단한 다과와 함께 작가들을 만날 기회도 있어요.","입장은 무료이고, 전시는 이달 말까지 이어지니 들를 시간은 충분해요."]}},"l_d01":{"q":{"l_d01_1":{"a":2,"why":"**'여러 핵을 가진 하나의 세포'**라고 했으니 단세포 덩어리인 C가 맞아요. 여러 생물의 무리(A)가 아니라 하나의 세포예요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 활동기의 점균은 무엇인가요?","opt":["작은 생물들의 무리","지능이 있는 종","단세포 덩어리","뇌와 유사한 기관"]}},"l_d01_2":{"a":1,"why":"**'쓸모없는 경로를 잘라 내고 효율적인 것만 남긴다'**고 했으니 B가 맞아요. 공학자 설계는 결과가 그것과 '비슷하다'는 비유일 뿐 베끼는 건 아니에요(D).","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 점균은 어떻게 효율적인 망을 만드나요?","opt":["가능한 여러 방향으로 고르게 퍼져서","쓸모없는 경로를 버리고 좋은 것을 유지해서","다른 점균이 남긴 자취를 따라가서","훈련된 공학자의 설계를 베껴서"]}},"l_d01_3":{"a":0,"why":"점액 자취를 **'일종의 외부 기억'**이라 설명하며 이미 지난 곳을 피하게 해 준다고 했어요. 기억 능력을 보이려는 것이라 A가 맞아요. 오히려 되짚기를 '피한다'고 했으니 B와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 점균이 남기는 점액 자취를 언급하나요?","opt":["기억 능력을 보여 주려고","점균이 원래 경로로 되돌아가는 법을 설명하려고","이 생물이 먹이를 소화하는 방식을 보이려고","다른 점균이 점균을 추적하는 법을 묘사하려고"]}},"l_d01_4":{"a":2,"why":"**'결정을 내리는 뇌가 전혀 없이도 지능이 얼마나 생겨날 수 있는지 묻게 만든다'**고 했으니 C가 맞아요. 그래서 뇌가 필수라는 A·B와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 지능에 대해 무엇을 시사하나요?","opt":["특화된 뉴런 없이는 불가능하다","통제 중심 역할을 하는 뇌가 필요하다","뇌와의 직접 연결 없이도 생길 수 있다","세포가 많은 생물에서만 발달한다"]}}},"script":[{"sp":"W","text":"When we talk about intelligence, we usually assume it requires a brain—neurons, wiring, some central place where thinking happens. So it's genuinely unsettling to meet an organism that solves problems and appears to make decisions, yet has no brain at all, no neurons, not even more than a single cell. That organism is the slime mold. In its active form it's a spreading yellow blob, a single cell with many nuclei, oozing across the forest floor in search of food. Drop bits of oat in a dish and the slime mold will send out exploring tendrils in every direction. Where it finds nothing, it withdraws. Where it finds food, it thickens the connection. Over hours, it prunes away the useless routes and keeps the efficient ones, until it has linked the food sources with a network often startlingly close to what a trained engineer would design. It gets stranger. The slime mold seems to leave a trail of slime behind it and avoid areas it has already crossed—a kind of external memory that lets it search fresh ground rather than retracing its steps. In a sense, it offloads remembering onto the environment itself. None of this involves thought as we know it. What looks like planning is really countless local chemical reactions adding up to sensible behavior. And that's the deeper puzzle here: it forces us to ask how much of what we call intelligence might emerge without any brain doing the deciding at all."}],"kr":{"passage":["지능을 이야기할 때 우리는 보통 그것이 뇌를 필요로 한다고 가정합니다. 뉴런, 회로, 사고가 일어나는 중심 장소 같은 것 말이죠. 그래서 뇌가 전혀 없고 뉴런도 없으며 심지어 세포 하나에 불과한데도 문제를 풀고 결정을 내리는 듯한 생물을 만나면 정말 당혹스럽습니다. 그 생물이 바로 점균(slime mold)입니다.","활동기의 점균은 퍼져 나가는 노란 덩어리로, 여러 개의 핵을 가진 하나의 세포이며, 먹이를 찾아 숲 바닥을 기어다닙니다. 접시에 귀리 조각을 놓으면 점균은 사방으로 탐색용 가지를 뻗습니다. 아무것도 없는 곳에서는 물러나고 먹이가 있는 곳에서는 연결을 두껍게 합니다. 몇 시간에 걸쳐 쓸모없는 경로를 잘라 내고 효율적인 것만 남겨, 훈련받은 공학자가 설계할 법한 것에 놀랍도록 가까운 망으로 먹이원들을 연결합니다.","더 놀라운 점이 있습니다. 점균은 지나온 자리에 점액 자취를 남기고 이미 지난 구역을 피하는 듯한데, 이는 발자취를 되짚는 대신 새 땅을 탐색하게 해 주는 일종의 외부 기억입니다. 말하자면 '기억하기'를 환경 자체에 떠넘기는 셈이죠.","이 중 어느 것도 우리가 아는 의미의 사고를 포함하지 않습니다. 계획처럼 보이는 것은 사실 수많은 국소적 화학 반응이 합쳐져 합리적인 행동으로 나타난 것입니다. 그리고 여기에 더 깊은 수수께끼가 있습니다. 우리가 지능이라 부르는 것의 얼마만큼이, 결정을 내리는 뇌가 전혀 없이도 생겨날 수 있는가를 묻게 만든다는 점입니다."]}},"l_a16":{"q":{"l_a16_1":{"a":0,"why":"운영 시간 안내에 **내일 들르겠다**고 반응한 A가 맥락에 맞아요. B는 run을 '뛰다'로 받은 함정, D는 관련 없는 넋두리예요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["잘됐네요, 내일 한번 들를게요.","그 선생님은 꽤 빨리 뛰어요.","우리 이번 주말에 캠퍼스 투어해요.","수학은 한 번도 쉬웠던 적이 없어요."]}}},"script":[{"sp":"M","text":"Math tutoring runs weekday afternoons until six."}],"kr":{"passage":["수학 튜터링은 평일 오후 6시까지 운영해요."]}},"l_a17":{"q":{"l_a17_1":{"a":3,"why":"연결해 달라는 요청에 **선호 시간을 되물으며** 절차를 진행한 D가 자연스러워요. A는 match를 '경기'로 받은 함정, C는 '어디' 답이라 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 경기는 무승부로 끝났어요.","네, 튜터링 도움이 될 것 같아요.","러닝 커먼스 쪽에 있어요.","선호하는 시간대가 있으세요?"]}}},"script":[{"sp":"W","text":"Can you match me with a peer tutor?"}],"kr":{"passage":["또래 튜터와 연결해 주실 수 있나요?"]}},"l_a18":{"q":{"l_a18_1":{"a":2,"why":"개강 안내에 **그거 신청해 볼까 한다**고 관심을 보인 C가 알맞아요. A·B는 skills·workshop→skillfully·worship 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 사람은 질문을 능숙하게 피했어요.","그들은 저 오래된 예배당에서 예배를 봐요.","그거 한번 신청해 볼까 봐요.","월요일은 늘 너무 바빠요."]}}},"script":[{"sp":"M","text":"The study skills workshop starts next Monday."}],"kr":{"passage":["학습법 워크숍이 다음 주 월요일에 시작해요."]}},"l_a19":{"q":{"l_a19_1":{"a":1,"why":"'누가' 봐 줄 수 있냐는 물음에 **필요한 도움 종류에 따라 담당이 다르다**고 답한 B가 맞아요. C는 draft를 '외풍'으로 받은 함정, A는 '언제' 답이라 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["아마 다음 주 초쯤일 거예요.","어떤 도움이 필요한지에 따라 달라요.","여기 찬 바람이 들어와요.","네, 거의 다 끝났어요."]}}},"script":[{"sp":"W","text":"Who can look over my thesis draft?"}],"kr":{"passage":["제 논문 초안을 봐 줄 사람이 누구일까요?"]}},"l_a20":{"q":{"l_a20_1":{"a":0,"why":"제안에 **그러면 도움이 되겠다**고 수락한 A가 자연스러워요. B는 partner를 반복한 함정, C는 '어디' 답이라 제안 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 그러면 큰 도움이 될 것 같아요.","제 실습 파트너가 이사 갔어요.","아래층 어학 실습실에서요.","그 얼룩은 쉽게 안 지워져요."]}}},"script":[{"sp":"M","text":"Would you like a Spanish conversation partner?"}],"kr":{"passage":["스페인어 회화 파트너 구해 드릴까요?"]}},"l_a21":{"q":{"l_a21_1":{"a":3,"why":"'왜' 인기냐는 이유를 묻는 말에 **중간고사 스트레스 때문**이라고 원인을 답한 D가 정확해요. A는 popular→poplar 소리 함정, C는 예/아니오라 why와 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저 포플러 나무는 정말 크네요.","주로 화요일 저녁이에요.","네, 작년부터 꽤 인기였어요.","다들 중간고사 때문에 스트레스받고 있잖아요."]}}},"script":[{"sp":"W","text":"Why is stats tutoring so popular lately?"}],"kr":{"passage":["요즘 통계 튜터링이 왜 이렇게 인기 많죠?"]}},"l_a22":{"q":{"l_a22_1":{"a":1,"why":"'어떻게' 재설정하냐는 물음에 **이메일 하단 링크를 쓰라**고 방법을 알려 준 B가 맞아요. A는 reset과 소리가 비슷한 upset 함정, C·D는 방법과 무관해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 일로 너무 속상해하지 마세요.","이메일 하단의 링크를 이용하세요.","글쎄요, 제 건 잘 되는데요.","안내 데스크 직원이 근무 중이에요."]}}},"script":[{"sp":"M","text":"How can I reset my account password?"}],"kr":{"passage":["계정 비밀번호를 어떻게 재설정하나요?"]}},"l_b03":{"q":{"l_b03_1":{"a":2,"why":"남자가 **'어제부터 다리를 전다'**고 했어요(C). B는 '조금은 체중을 싣는다'는 말과 어긋나고, D는 '가시일 수도 있다'는 추측을 사실로 단정한 오답이에요.","wrong":[null,null,null,null],"kr":{"stem":"남자가 말하는 문제는 무엇인가요?","opt":["아무것도 안 먹으려 함","전혀 걷지 못함","한쪽 다리를 아껴 디딤","날카로운 가시를 삼킴"]}},"l_b03_2":{"a":3,"why":"수의사가 **'삐었거나 가시일 수도 있다'**며 여러 가능성을 열어 두고 우선 살펴보겠다고 했어요. 원인이 아직 확정되지 않았다는 뜻이라 D가 맞고, A(즉시 수술)는 단정이 지나쳐요.","wrong":[null,null,null,null],"kr":{"stem":"강아지의 부상에 대해 알 수 있는 것은?","opt":["반드시 즉시 수술이 필요함","전혀 통증이 없음","거친 야외 놀이로 생김","정확한 원인은 아직 불확실함"]}}},"script":[{"sp":"M","text":"Could you take a look at my dog? He's been limping since yesterday."},{"sp":"W","text":"Of course. Is he putting any weight on the leg?"},{"sp":"M","text":"A little, but he whines when he walks."},{"sp":"W","text":"It could be a sprain or maybe a thorn in his paw."},{"sp":"M","text":"Do you think he'll need an X-ray?"},{"sp":"W","text":"Maybe, but let me examine him first. I just wanted to make sure there wasn't another reason."},{"sp":"M","text":"Okay. He gets nervous at the vet, just so you know."},{"sp":"W","text":"Don't worry, I'm used to situations like this. we'll go slow and keep him calm."},{"sp":"M","text":"Thanks. I really appreciate that."}],"kr":{"passage":["남: 제 강아지 좀 봐 주시겠어요? 어제부터 다리를 절어요.","여: 그럼요. 그 다리에 체중을 싣긴 하나요?","남: 조금은요, 그런데 걸을 때 낑낑거려요.","여: 삐었거나 발바닥에 가시가 박혔을 수도 있어요.","남: 엑스레이가 필요할까요?","여: 그럴 수도요, 우선 제가 살펴볼게요. 다른 원인은 없는지 확인하려던 거예요.","남: 알겠어요. 참고로 얘가 병원에서 긴장을 많이 해요.","여: 걱정 마세요, 이런 상황엔 익숙해요. 천천히 진행하면서 안정시킬게요.","남: 감사합니다. 정말 고마워요."]}},"l_b04":{"q":{"l_b04_1":{"a":2,"why":"남자가 **'멕시코에서 자랐다'**고 해 원어민임을 밝혔어요(C). 그가 늘리고 싶은 건 스페인어가 아니라 **영어 작문**이라 B는 반대이고, A(강의로 배움)도 사실과 달라요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 자신의 언어 배경에 대해 뭐라고 하나요?","opt":["대학 강의로 스페인어를 배웠다","스페인어 말하기를 늘리고 싶다","멕시코에서 스페인어를 쓰며 자랐다","영어 화자에게 스페인어를 가르친다"]}},"l_b04_2":{"a":0,"why":"남자가 마지막에 **'오늘 밤에 일정을 보내겠다'**고 했어요(A). 만남은 정해졌지만 '오늘 밤'의 행동은 일정 전송이에요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 오늘 밤 무엇을 할 가능성이 높나요?","opt":["여자에게 주간 일정을 보낸다","학생회관에서 만난다","파트너 구하는 글을 또 올린다","스페인어 작문을 연습한다"]}}},"script":[{"sp":"M","text":"Hey, are you the one who posted about wanting a Spanish-English exchange partner?"},{"sp":"W","text":"Yeah, that's me! Are you a native Spanish speaker?"},{"sp":"M","text":"Pretty much. I grew up in Mexico, and I'm trying to get my English writing up."},{"sp":"W","text":"Perfect, that's exactly what I need help with too. Wanna meet twice a week?"},{"sp":"M","text":"Sure. Maybe Tuesdays and Fridays? We could split it fifty-fifty, half Spanish, half English."},{"sp":"W","text":"Sounds fair. There's a quiet corner in the student union we could use."},{"sp":"M","text":"Great. I'll message you my schedule tonight."},{"sp":"W","text":"Awesome. Talk soon!"}],"kr":{"passage":["남: 저기, 스페인어-영어 교환 파트너 구한다고 올리신 분 맞으세요?","여: 네, 저예요! 스페인어 원어민이세요?","남: 거의요. 멕시코에서 자랐고, 영어 작문을 늘리려고요.","여: 딱이네요, 저도 바로 그게 필요하거든요. 일주일에 두 번 만날래요?","남: 좋아요. 화요일이랑 금요일 어때요? 반반, 절반은 스페인어 절반은 영어로 나눠요.","여: 좋아요. 학생회관에 조용한 구석 자리가 있어요.","남: 좋네요. 오늘 밤에 제 일정 보내 드릴게요.","여: 좋아요. 곧 봬요!"]}},"l_c03":{"q":{"l_c03_1":{"a":1,"why":"**'이제부터 분실물을 안내 데스크 뒤 캐비닛에 보관한다'**며 보관 장소가 바뀐 걸 알려요(B). 기부(D)는 마지막에 덧붙인 부수 정보일 뿐이라 주제가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"화자가 주로 알리는 것은 무엇인가요?","opt":["라운지 청소 새 일정","분실물 보관 장소 변경 안내","소파 근처 가방 금지 규칙","회수 물품 기부 정책"]}},"l_c03_2":{"a":3,"why":"**'직원에게 와서 물건을 설명하라'**고 했으니 D가 맞아요. 캐비닛은 '데스크 뒤'라 A(소파 옆)는 틀리고, 온라인 양식은 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"물건을 잃어버린 사람은 어떻게 하라고 하나요?","opt":["소파 옆 캐비닛을 살펴본다","온라인 분실물 양식을 작성한다","30일을 기다렸다가 찾는다","직원에게 물건을 설명한다"]}}},"script":[{"sp":"W","text":"Hey everyone, just a quick heads up about the lost items here in the lounge. From now on, we're keeping everything that's found in the cabinet behind the front desk instead of the basket by the couches. If you've lost a water bottle, charger, or umbrella, come ask the staff on duty and describe it. One more thing. Anything left longer than thirty days gets donated, so check soon if you're missing something."}],"kr":{"passage":["안녕하세요 여러분, 라운지 분실물에 대해 잠깐 알려 드려요. 이제부터 발견된 물건은 소파 옆 바구니가 아니라 안내 데스크 뒤 캐비닛에 보관해요.","물병이나 충전기, 우산을 잃어버렸다면 근무 중인 직원에게 와서 물건을 설명해 주세요.","한 가지 더요. 30일 넘게 방치된 물건은 기부되니, 잃어버린 게 있으면 서둘러 확인하세요."]}},"l_c04":{"q":{"l_c04_1":{"a":2,"why":"**'예전엔 남은 금액이 그냥 사라졌다'**고 했으니 C가 맞아요. 이월(A)은 '올해부터' 바뀐 새 방침이라 과거와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"예전에 남은 다이닝 달러는 어떻게 됐다고 하나요?","opt":["다음 봄으로 이월됐다","학생에게 환불됐다","학기 말에 사라졌다","식당 상품권으로 교환됐다"]}},"l_c04_2":{"a":1,"why":"**'쓰지 않은 금액이 봄으로 이월된다'**고 해 더는 소멸하지 않기 때문이에요(B). 영수증·계정 확인은 잔액 조회 방법일 뿐 서두르지 않아도 되는 이유는 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"학생들이 12월에 더는 서두르지 않아도 되는 이유는?","opt":["가을 학기가 더 길어져서","남은 잔액이 사라지지 않아서","영수증에 학생 계정이 표시돼서","잔액을 학생 계정에 추가할 수 있어서"]}}},"script":[{"sp":"M","text":"Good afternoon, everyone. We've got some good news about your dining dollars. In the past, any dining dollars left at the end of the fall term simply disappeared. Starting this year, whatever you don't spend will now carry over into the spring, so you won't have to rush to use them in December. Your balance is printed at the bottom of every receipt, and you can also check it on your student account. Enjoy the rest of your meal."}],"kr":{"passage":["안녕하세요 여러분. 다이닝 달러에 관한 반가운 소식이에요. 예전에는 가을 학기 말에 남은 다이닝 달러가 그냥 사라졌어요.","올해부터는 쓰지 않은 금액이 봄 학기로 이월돼요. 그래서 12월에 서둘러 다 쓸 필요가 없어요.","잔액은 모든 영수증 하단에 찍히고, 학생 계정에서도 확인할 수 있어요. 남은 식사 맛있게 하세요."]}},"l_a23":{"q":{"l_a23_1":{"a":1,"why":"모집 안내에 **몇 자리가 있는지 되물으며** 관심을 보인 B가 대화로 자연스러워요. C·D는 동아리·로봇에 대한 일반 감상이라 모집 정보에 반응하지 않아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 동아리는 꽤 인기 많아요.","자리가 몇 개나 있나요?","제 일상이 너무 바빠요.","로봇은 정말 흥미로운 것 같아요."]}}},"script":[{"sp":"W","text":"Our robotics club is recruiting new members."}],"kr":{"passage":["저희 로봇 동아리에서 신입 부원을 모집하고 있어요."]}},"l_a24":{"q":{"l_a24_1":{"a":3,"why":"정오에 시작한다는 안내에 **어디로 모이냐**고 이어 물은 D가 자연스러워요. A는 new를 '신제품'으로 받은 함정, B는 아직 안 나온 위치를 먼저 답해 어색해요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그건 새로 나온 거예요.","정문 바로 옆이에요.","이 캠퍼스 정말 넓네요.","어디로 모이면 되나요?"]}}},"script":[{"sp":"M","text":"If you're new, the tour starts at noon."}],"kr":{"passage":["처음 오셨다면, 투어는 정오에 시작해요."]}},"l_a25":{"q":{"l_a25_1":{"a":2,"why":"변경 가능하냐는 확인(부가의문문)에 **둘째 주까지 가능하다**고 기한을 답한 C가 맞아요. A는 plan→plane 소리 함정, B는 '어디' 답이라 예/아니오 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["비행기가 정시에 착륙했어요.","식당 서비스 데스크에서요.","네, 둘째 주까지는 가능해요.","음식은 사실 꽤 괜찮아요."]}}},"script":[{"sp":"W","text":"You can still change your meal plan, right?"}],"kr":{"passage":["식사 플랜 아직 변경할 수 있죠?"]}},"l_b05":{"q":{"l_b05_1":{"a":2,"why":"남자가 **'좀 멘붕이다'**라고 하자 여자가 'Don't lose your head yet'이라며 분실물 센터를 권했어요. 즉 **'아직 당황하지 마라'**는 뜻이라 C가 맞아요. 관용구라 '노트를 잃다'처럼 글자 그대로 받으면 안 돼요.","wrong":[null,null,null,null],"kr":{"stem":"남자가 \"Don't lose your head yet\"라고 한 말의 의미는?","opt":["노트를 또 잃어버리면 안 된다","먼저 강의실을 확인해야 한다","아직 당황할 필요는 없다","시험 걱정을 너무 많이 한다"]}},"l_b05_2":{"a":0,"why":"여자가 **'좀 눈에 안 띈다(a bit hidden)'**고 했어요(A). '사람들이 물건을 많이 갖다 놓는다'는 말은 이용자가 많다는 뜻이라 C(거의 없음)와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"분실물 센터에 대해 추론할 수 있는 것은?","opt":["눈에 잘 안 띌 수 있다","교외에 있다","이용하는 학생이 거의 없다","미리 예약해야 한다"]}}},"script":[{"sp":"M","text":"I think I left my notebook in the lecture hall this morning."},{"sp":"W","text":"Oh no. Was it that blue one you're always carrying around?"},{"sp":"M","text":"Yeah, all my notes for the exam are in it. I'm kind of panicking."},{"sp":"W","text":"Don't lose your head yet. Did you check the lost-and-found at the student center?"},{"sp":"M","text":"I didn't even know we had one."},{"sp":"W","text":"It's a bit hidden, but it's right by the administration office. People turn in stuff there left and right."},{"sp":"M","text":"That's a relief. I'll head over there right now."},{"sp":"W","text":"Good luck. Text me if you can't find it."}],"kr":{"passage":["남: 오늘 아침에 강의실에 노트를 두고 온 것 같아요.","여: 이런. 늘 들고 다니던 그 파란 노트요?","남: 네, 시험 대비 노트가 다 거기 있어요. 좀 멘붕이에요.","여: 아직 당황하긴 일러요. 학생회관 분실물 센터는 확인해 봤어요?","남: 그런 게 있는 줄도 몰랐어요.","여: 좀 눈에 안 띄는데, 행정실 바로 옆이에요. 사람들이 물건을 거기 엄청 많이 갖다 놔요.","남: 다행이네요. 지금 바로 가 볼게요.","여: 행운을 빌어요. 못 찾으면 문자해요."]}},"l_b06":{"q":{"l_b06_1":{"a":0,"why":"여자가 **2층으로 옮겼다**고 했고 이어 **수요일 대신 목요일**로 바뀌었다고 해, 방과 요일이 모두 변했어요(A). C는 '지하에서 나온' 것이라 반대이고, B도 요일 방향이 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"프랑스어 회화 동아리에 생긴 변화는 무엇인가요?","opt":["방과 요일이 모두 바뀌었다","다시 수요일로 바뀌었다","위치를 지하로 바꿨다","이번 학기에 모임을 중단했다"]}},"l_b06_2":{"a":2,"why":"남자가 방 이동엔 **'저는 좋아요'**, 요일 변경엔 **'저한테 오히려 낫다'**고 해 두 변화 모두 반겼어요(C). 목요일에 수업이 일찍 끝나 편하다고 했으니 D(겹칠 걱정)와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 새 모임 요일에 대해 어떻게 느끼나요?","opt":["갑작스러운 일정 변경에 짜증 남","새 요일에 무관심함","변화가 마음에 듦","수업과 겹칠까 걱정함"]}}},"script":[{"sp":"W","text":"Did you hear the French conversation club moved to a new room?"},{"sp":"M","text":"Oh, that's why. I showed up at the old spot last week and it was empty."},{"sp":"W","text":"Yeah, they bumped us to the language center on the second floor."},{"sp":"M","text":"Actually, I like that. That basement room was always packed like sardines."},{"sp":"W","text":"Right? And now we meet on Thursdays instead of Wednesdays."},{"sp":"M","text":"Oh, that's actually better for me. My last class ends early on Thursdays."},{"sp":"W","text":"Nice. So I'll see you there this week?"},{"sp":"M","text":"For sure. I'll bring the coffee this time."},{"sp":"W","text":"Deal!"}],"kr":{"passage":["여: 프랑스어 회화 동아리가 새 방으로 옮긴 거 들었어요?","남: 아 그래서였구나. 지난주에 예전 자리로 갔더니 텅 비어 있더라고요.","여: 네, 2층 어학 센터로 옮겨졌어요.","남: 사실 저는 좋아요. 그 지하 방은 늘 콩나물시루처럼 붐볐잖아요.","여: 그렇죠? 그리고 이제 수요일 대신 목요일에 모여요.","남: 오, 그건 저한테 오히려 나아요. 목요일엔 마지막 수업이 일찍 끝나거든요.","여: 좋네요. 그럼 이번 주에 거기서 봐요?","남: 물론이죠. 이번엔 제가 커피 사 갈게요.","여: 좋아요!"]}},"l_d02":{"q":{"l_d02_1":{"a":1,"why":"**'저장고가 바닥날수록 판단의 질이 떨어진다'**며 결정 능력이 소진되는 원리를 다뤄요(B). 이른 아침 권고(C)는 결론의 일부일 뿐이고, '영구히 망친다'(D)는 과장이에요.","wrong":[null,null,null,null],"kr":{"stem":"이 강의는 주로 무엇에 관한 것인가요?","opt":["좋은 선택으로 의지력이 약해지는 방식","건전한 선택을 내리는 정신 능력이 떨어지는 방식","왜 결정을 이른 아침에 내려야 하는지","스트레스가 의사결정 능력을 영구히 망치는 방식"]}},"l_d02_2":{"a":2,"why":"지치면 **'수동적으로 변해 기본값을 그대로 받아들인다'**고 했으니 C가 맞아요. 충동형도 '가장 쉬워 보이는' 선택이라 '더 어렵다'는 D는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 정신적으로 지친 사람은 어떻게 하는 경향이 있나요?","opt":["믿을 만한 친구나 가족에게 조언을 구한다","복잡한 문제에 더 예리하게 집중한다","적극적으로 생각하지 않고 기본값을 그대로 받아들인다","보통 더 어려운 충동적 선택을 한다"]}},"l_d02_3":{"a":0,"why":"판사 연구는 **결정 피로가 가석방 같은 중대한 판단에도 영향을 준다**는 걸 보여 주는 예시라 A가 맞아요. 편향(C)이나 휴식 권고(B)가 요지가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 판사와 가석방 연구를 언급하나요?","opt":["피로가 고위험 결정에 어떻게 영향을 주는지 보여주려고","판사가 휴식을 더 취해야 함을 증명하려고","판사가 일부 수감자에게 편향돼 있다고 주장하려고","법원이 일정을 어떻게 짜야 하는지 설명하려고"]}},"l_d02_4":{"a":1,"why":"**'가장 중요한 결정은 생생할 때로 잡으라'**고 했으니 B가 맞아요. 시점이 노력만큼 중요하다는 취지라 C와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 중요한 결정의 시점에 대해 무엇을 시사하나요?","opt":["다음 날 아침까지 미뤄야 한다","다루기 전에 생생한 상태가 결과를 좋게 한다","시점보다 순수한 노력이 더 중요하다","많은 이전 사건을 처리하는 과정을 거쳐야 한다"]}}},"script":[{"sp":"M","text":"Have you ever noticed that by the end of a long day, even simple choices feel exhausting? Should you cook or order in? Which show should you watch? That drained feeling has a name in psychology: decision fatigue. The idea is that our capacity to make good decisions is not unlimited. Every choice we make, from what to wear to how to reply to an email, draws on the same pool of mental energy. As that pool runs low, the quality of our judgment tends to decline. Now, when people are mentally worn out, they often drift toward one of two shortcuts. Some become impulsive, grabbing whatever option feels easiest in the moment. Others become passive, avoiding decisions altogether and simply accepting the default. Neither shortcut reflects careful thinking; both are signs that the mind is trying to conserve effort. A well-known study of judges illustrates this pattern. Researchers found that prisoners who appeared early in the morning were far more likely to be granted parole than those seen just before a break, when the judge had already processed many cases. The law had not changed, only the mental state of the decision-maker. This has practical consequences. It suggests we should schedule our most important decisions for times when we are fresh, and reduce the number of trivial choices competing for our attention. If your mind is a limited resource, spending it wisely may matter as much as how hard you think."}],"kr":{"passage":["긴 하루가 끝날 무렵이면 간단한 선택조차 지치게 느껴진 적 있나요? 요리할까 시켜 먹을까? 어떤 프로를 볼까? 그 지친 느낌에는 심리학 용어가 있습니다. 바로 '결정 피로(decision fatigue)'입니다. 좋은 결정을 내리는 우리의 능력은 무한하지 않다는 개념이죠. 무엇을 입을지부터 이메일에 어떻게 답할지까지 우리가 내리는 모든 선택은 같은 정신 에너지 저장고에서 끌어다 씁니다. 그 저장고가 바닥날수록 판단의 질은 떨어지는 경향이 있습니다.","정신적으로 지치면 사람들은 흔히 두 가지 지름길 중 하나로 흘러갑니다. 어떤 이는 충동적으로 그 순간 가장 쉬워 보이는 선택지를 덥석 잡습니다. 다른 이는 수동적으로 변해 결정을 아예 피하고 기본값을 그대로 받아들입니다. 두 지름길 모두 신중한 사고가 아니라, 마음이 노력을 아끼려 한다는 신호입니다.","판사에 관한 유명한 연구가 이 양상을 잘 보여 줍니다. 연구자들은 이른 아침에 출석한 수감자가, 판사가 이미 많은 사건을 처리한 휴식 직전에 심리받은 이들보다 가석방을 훨씬 더 많이 허가받았음을 발견했습니다. 법이 바뀐 게 아니라 결정하는 사람의 정신 상태만 바뀐 것입니다.","이는 실용적 함의를 갖습니다. 가장 중요한 결정은 우리가 생생할 때로 잡고, 주의를 다투는 사소한 선택의 수를 줄여야 한다는 것이죠. 마음이 한정된 자원이라면, 그것을 현명하게 쓰는 일이 얼마나 열심히 생각하느냐만큼 중요할 수 있습니다."]}},"l_d03":{"q":{"l_d03_1":{"a":2,"why":"**'규모뿐 아니라 많은 부분이 수수께끼로 남아 있다'**며 발달했으나 미스터리한 문명을 다뤄요(C). 문자는 '해독 못 했다'고 했으니 D는 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"이 강의는 주로 무엇에 관한 것인가요?","opt":["고대 사회의 증거를 발견하기가 얼마나 어려운지","왜 인더스 문명이 예상보다 컸는지","정교하지만 수수께끼로 남은 고대 문명","학자들이 인더스 문자를 마침내 해독한 방법"]}},"l_d03_2":{"a":3,"why":"**'세계 여러 곳에서 수천 년 뒤에야 필적할 만한 정교한 하수 체계'**라고 했으니 D가 맞아요. 지배층만(B)이나 이집트 유래(C)는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 인더스 도시의 벽돌 배수로에 대해 뭐라고 하나요?","opt":["도시 전성기 한참 뒤에 추가됐다","도시의 지배층만 이용했다","설계를 고대 이집트에서 가져왔다","오랫동안 필적할 것이 없는 하수 체계를 이뤘다"]}},"l_d03_3":{"a":1,"why":"해독 실패를 들며 **'이름도 믿음도 통치자의 말도 읽을 수 없다'**고 해, 여전히 미지로 남은 부분을 강조해요(B). 문자를 남겼으니 '거의 안 남겼다'(A)는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 해독되지 않은 인더스 문자를 언급하나요?","opt":["인더스 사람들이 기록을 거의 안 남겼음을 증명하려고","그들에 대해 얼마나 많은 것이 미지로 남았는지 강조하려고","그것이 얼마나 가치 있는지 설명하려고","그 문자가 이집트 상형문자와 일치함을 보이려고"]}},"l_d03_4":{"a":2,"why":"**'궁전·신전·군대의 뚜렷한 증거가 없어 어떻게 통치됐는지 의문'**이라 했으니, 통치 방식은 아직 알 수 없어요(C). 그래서 군주(A)·군대(B)·종교(D) 단정은 근거가 없어요.","wrong":[null,null,null,null],"kr":{"stem":"인더스 사회가 어떻게 통치됐는지에 대해 추론할 수 있는 것은?","opt":["강력한 군주가 다스렸다","궁전과 군대로 백성을 통제했다","통치 방식을 아직 밝혀낼 수 없다","종교 지도자가 통치했다"]}}},"script":[{"sp":"W","text":"Around four and a half thousand years ago, one of the largest civilizations of the ancient world covered an area bigger than ancient Egypt and Mesopotamia combined, yet almost no one has heard of it. This was the Indus Valley civilization, spread across what is now Pakistan and northwestern India. What makes it so striking is not only its size but how much about it remains a mystery. Its cities were astonishingly advanced. Places like Mohenjo-daro were laid out on precise grids, with streets meeting at right angles. Homes had private bathrooms connected to covered brick drains running beneath the streets, a sophisticated sewage system that would not be matched in many parts of the world for thousands of years. The bricks themselves were made to standard proportions across hundreds of miles, suggesting careful planning and shared standards. And here lies the great puzzle. The Indus people left behind a written script, carved on small seals and tablets. Despite over a century of effort, no scholar has managed to decipher it. We cannot read their names, their beliefs, or their rulers' words. Even more curiously, archaeologists have found no clear evidence of grand palaces, temples, or armies, raising questions about how such a vast society was governed. So we are left admiring a civilization we can see but cannot hear. Its careful cities speak of order and skill, while its silent script guards secrets that, for now, remain entirely beyond our reach."}],"kr":{"passage":["약 4천 5백 년 전, 고대 세계에서 가장 큰 문명 중 하나가 고대 이집트와 메소포타미아를 합친 것보다 넓은 지역을 뒤덮었지만, 그것을 들어 본 사람은 거의 없습니다. 바로 지금의 파키스탄과 인도 북서부에 걸쳐 있던 인더스 문명입니다. 이 문명이 인상적인 것은 규모뿐 아니라 그에 관한 많은 부분이 여전히 수수께끼로 남아 있다는 점입니다.","그 도시들은 놀랍도록 발달해 있었습니다. 모헨조다로 같은 곳은 도로가 직각으로 만나는 정밀한 격자로 배치됐습니다. 집에는 거리 아래로 흐르는 덮인 벽돌 배수로에 연결된 개인 욕실이 있었는데, 이는 세계 여러 곳에서 수천 년 뒤에야 필적할 만한 정교한 하수 체계였습니다. 벽돌 자체도 수백 마일에 걸쳐 표준 규격으로 만들어져, 세심한 계획과 공유된 표준을 짐작하게 합니다.","그리고 여기에 큰 수수께끼가 있습니다. 인더스 사람들은 작은 인장과 판에 새긴 문자를 남겼습니다. 한 세기가 넘는 노력에도 어떤 학자도 그것을 해독하지 못했습니다. 우리는 그들의 이름도, 믿음도, 통치자의 말도 읽을 수 없습니다.","더욱 흥미롭게도, 고고학자들은 웅장한 궁전이나 신전, 군대의 뚜렷한 증거를 찾지 못해, 이토록 방대한 사회가 어떻게 통치됐는지 의문을 남깁니다. 그래서 우리는 볼 수는 있지만 들을 수는 없는 문명을 바라보게 됩니다. 정연한 도시는 질서와 기술을 말해 주지만, 침묵하는 문자는 지금으로선 우리 손이 전혀 닿지 않는 비밀을 지키고 있습니다."]}},"w_bas_01":{"items":[{"id":"w_bas_01_1","solution":["the one","who","had","more","experience"],"answer":"The one who had more experience."},{"id":"w_bas_01_2","solution":["asked","me","why","the interview","went","so well"],"answer":"She asked me why the interview went so well."},{"id":"w_bas_01_3","solution":["where","did","they","find","the","missing","files"],"answer":"Where did they find the missing files?"},{"id":"w_bas_01_4","solution":["the","boss","gave","us","a","bonus"],"answer":"The boss gave us a bonus."},{"id":"w_bas_01_5","solution":["offered","to take","responsibility","for","the","mistake"],"answer":"He offered to take responsibility for the mistake."},{"id":"w_bas_01_6","solution":["taking","the train","much","faster","than","driving there"],"answer":"Taking the train is much faster than driving there."},{"id":"w_bas_01_7","solution":["was","built","by","a","local","construction","company"],"answer":"It was built by a local construction company."},{"id":"w_bas_01_8","solution":["the team","has","not","made","a","final","decision"],"answer":"The team has not made a final decision yet."},{"id":"w_bas_01_9","solution":["should","not","be","late","for","the","meeting"],"answer":"You should not be late for the meeting."},{"id":"w_bas_01_10","solution":["sells","a","wide","range","of","organic","products"],"answer":"The store sells a wide range of organic products."}],"kr":{"items":[{"prompt_ko":"두 지원자 중 누가 합격했나요?","answer_ko":"경력이 더 많았던 사람이요.","note":"**관계절(who ...)**로 명사를 꾸미는 구조예요. **The one**(그 사람)을 주어로 놓고 뒤에 **who had more experience**(경력이 더 많았던)를 붙여 '어떤 사람'인지 설명해요. who는 사람을 받는 주격 관계대명사라 바로 뒤에 동사(had)가 와요."},{"prompt_ko":"채용 라운드 뒤에 매니저가 궁금해하는 것 같았어요.","answer_ko":"그분은 왜 면접이 그렇게 잘됐는지 저에게 물었어요.","note":"**간접의문문**이에요. ask + 사람 + **why + 주어 + 동사** 순서로, 의문문이 문장 속에 들어가면 **'why the interview went'**처럼 «의문사+주어+동사» 평서문 어순이 돼요(did 같은 조동사 안 써요)."},{"prompt_ko":"누군가 드디어 잃어버린 서류를 찾았어요.","answer_ko":"그들이 사라진 파일을 어디서 찾았나요?","note":"**직접 의문문(Wh-)** 구조예요. **Where + did + 주어 + 동사원형(find)** 순서로, 과거시제라 **did**를 쓰고 뒤 동사는 원형으로 돌아가요. 물음표로 끝나요."},{"prompt_ko":"오늘 왜 다들 이렇게 기분이 좋아요?","answer_ko":"사장님이 우리에게 보너스를 주셨어요.","note":"**4형식(수여동사)** 문장이에요. **give + 사람(us) + 사물(a bonus)** 순서로 '~에게 ~을 주다'를 나타내요. 간접목적어(us)가 직접목적어(a bonus)보다 앞에 와요."},{"prompt_ko":"다니엘은 그 항의에 어떻게 반응했나요?","answer_ko":"그는 그 실수에 책임지겠다고 했어요.","note":"**offer + to부정사** 구조예요. offer(제안하다)는 뒤에 **to+동사원형**을 취해 **to take responsibility**(책임지겠다고)로 이어져요. **take responsibility for**(~에 책임지다)는 자주 쓰는 표현이에요."},{"prompt_ko":"기차를 탈까요, 아니면 그냥 운전할까요?","answer_ko":"기차를 타는 게 거기까지 운전하는 것보다 훨씬 빨라요.","note":"**비교급(faster than)** 구조예요. 주어로 **동명사 Taking the train**을 쓰고 **much faster than driving**으로 두 행동을 비교해요. **much**는 비교급을 강조해 '훨씬'을 더해요."},{"prompt_ko":"이 오래된 다리 정말 인상적이네요.","answer_ko":"그건 지역 건설 회사가 지었어요.","note":"**수동태(be + 과거분사)** 구조예요. **It was built by ...**로 '~에 의해 지어졌다'를 나타내요. 행위자는 **by** 뒤에 놓아요(a local construction company)."},{"prompt_ko":"파트너들이 새 계획에 합의했나요?","answer_ko":"팀은 아직 최종 결정을 내리지 않았어요.","note":"**현재완료(has + p.p.)** 구조예요. **has not made**로 '아직 ~하지 않았다'를 나타내고 문장 끝 **yet**과 짝을 이뤄요. 부정은 has와 made 사이에 not을 넣어요."},{"prompt_ko":"오늘 좀 늦게 나갈까 생각 중이에요.","answer_ko":"회의에 늦으면 안 돼요.","note":"**조동사 should** 구조예요. **should + not + 동사원형(be)**로 '~하면 안 된다'는 조언을 나타내요. **be late for**(~에 늦다)는 굳어진 표현이에요."},{"prompt_ko":"그 가게는 어떤 물건을 취급하나요?","answer_ko":"그 가게는 다양한 유기농 제품을 팔아요.","note":"**명사구**가 핵심이에요. **a wide range of + 복수명사**는 '다양한 ~'를 뜻하는 덩어리 표현이라 통째로 외워요(a wide range of organic products)."}]}},"w_em_01":{"model":"","rubric":[],"kr":{"situation_ko":"당신은 대학 중앙 식당의 식사 플랜을 이용해요. 지난 2주간 점심 줄이 너무 길어져 수업 사이에 제대로 식사하기 어려웠어요. 식당 서비스 담당자인 카스텔라노 씨에게 이 문제를 알리는 이메일을 써요.","directions_ko":["점심 시간에 겪은 문제를 설명해요.","이 문제가 일상에 어떤 영향을 주는지 설명해요.","상황을 개선할 변화를 제안해요."]}},"w_ad_01":{"model":"","rubric":[],"kr":{"prof_ko":"문화 보존 단원에서 우리는 사회가 전통을 어떻게 이어 가는지 살펴봤어요. 한 접근은 박물관·아카이브·공식 유산 프로그램 같은 공식 기관에 기대어 문화를 보호·기록해요. 다른 접근은 평범한 가정이 전통을 매일 실천할 때 가장 잘 살아남는다고 봐요. 공동체의 유산을 지키는 데 어느 쪽이 더 설득력 있다고 보나요, 그 이유는요?","posts_ko":[{"name":"Marcus","text_ko":"저는 공식 기관이 꼭 필요하다고 확신해요. 박물관·아카이브는 가정이 못 하는 취약한 유물을 보호하고, 훈련된 큐레이터가 정확한 기록을 남겨요. 공식 유산 프로그램이 없으면 기억하는 사람이 사라지는 순간 언어와 공예가 조용히 사라져요."},{"name":"Grace","text_ko":"마커스와 달리, 저는 문화가 유리 진열장이 아니라 일상 실천 속에 산다고 봐요. 박물관에 보존된 전통은 생명 없는 전시물이 돼요. 조부모가 지역 음식을 만들거나 방언을 가르칠 때, 그 관습은 의미를 유지하며 자연스럽게 이어져요."}]}},"s_lr_01":{"items":[{"n":1,"text":"Find help at the campus shuttle information desk."},{"n":2,"text":"Live arrival times are shown on the screen."},{"n":3,"text":"Printed schedules are stocked in the brochure rack."},{"n":4,"text":"There is a large route map on the wall."},{"n":5,"text":"The ticket machine, which is quite tall, stands beside the information desk. "},{"n":6,"text":"Our comfortable waiting benches seat over twenty commuting students at once."},{"n":7,"text":"If you need to wait a while, feel free to grab a drink at the water cooler nearby."}]},"s_iv_01":{"items":[{"n":1,"text":"First, I'd like to know about your experience with museums. How often do you visit museums or art galleries, and what types do you enjoy most—history, science, or fine art? Think about the last one you visited."},{"n":2,"text":"Got it. Can you describe what you usually do during a typical museum visit, from the moment you arrive to when you leave? Please walk me through how you like to explore the exhibits."},{"n":3,"text":"Great. If you were asked to curate your own exhibition in a local gallery, what theme or subject would you choose, and what kind of works would you display to draw visitors in?"},{"n":4,"text":"Great. Some people believe that governments should fully fund museums so that everyone can visit them for free, since access to art and history benefits the whole society. Do you agree or disagree? Why?"}]}}};
